<script setup lang="ts">
import {instrumentLabel,instrumentName} from '../utils/instrumentNames'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {Activity,BellRing,Plus,RefreshCw} from 'lucide-vue-next'
import {monitoringApi,type MonitorAsset,type MonitorCatalog,type MonitorJob,type MonitorEvent,type MonitorParameters,type OutcomePattern} from '../services/monitoring'
import {hasPermission} from '../services/auth'
import {formatTime} from '../utils/format'
const emit=defineEmits<{inspect:[symbol:string]}>()
const props=withDefaults(defineProps<{assetType:MonitorAsset;symbol:string;paused?:boolean}>(),{paused:false})
const catalog=ref<MonitorCatalog|null>(null),jobs=ref<MonitorJob[]>([]),events=ref<MonitorEvent[]>([])
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),eventQuery=ref(''),jobPage=ref(1),eventPage=ref(1),jobTotal=ref(0),eventTotal=ref(0),monitorFilter=ref(''),unread=ref(false)
const editor=ref<{id?:string;name:string;symbol:string;enabled:boolean;seconds:number;version:number;parameters:MonitorParameters}|null>(null)
const confirmation=ref<{title:string;detail:string;action:()=>Promise<unknown>}|null>(null),detail=ref<MonitorEvent|null>(null)
const resource=computed(()=>props.assetType==='OPTION'?'options':'market'),canWrite=computed(()=>hasPermission(resource.value+'.write'))
const kindLabel=computed(()=>props.assetType==='OPTION'?'期权':'期货')
const states:Record<string,string>={STARTING:'等待检查',WARMING:'窗口预热',READY:'运行中',STALE:'行情过时 / 休市',ERROR:'等待重试',FORBIDDEN:'权限暂停',PAUSED:'已暂停',EXPIRED:'已到期'}
let alive=true,version=0,timer:number|undefined
const featureNames:Record<string,string>={dayMA5DistancePct:'价格距日线MA5%',dayMA20DistancePct:'价格距日线MA20%',dayMA20Slope5Pct:'日线MA20五日斜率%',dayMA5vs20Pct:'日线MA5相对MA20%',minuteMA20DistanceATR:'价格距15分MA20/ATR',minuteMA5vs20ATR:'15分MA5−MA20/ATR',minuteMA20Slope5ATR:'15分MA20五柱斜率/ATR',macdHistogramATR:'MACD柱/ATR',rsi14Simple:'RSI14（简单平均）',volumeRatio20:'柱量/此前20柱均量',atrPct:'15分ATR/价格%',closeLocation:'收盘位置（低0高1）',bodyATR:'实体/ATR',return4ATR:'过去4柱变动/ATR',oiChange5Pct:'持仓量5柱变化%'}
function probability(value:number|null|undefined){return typeof value==='number'&&Number.isFinite(value)?(value*100).toFixed(1)+'%':'—'}
function pathText(pattern:OutcomePattern){return pattern.path.map(r=>(featureNames[r.feature]??r.feature)+(r.operator==='LE'?' ≤ ':' > ')+statistic(r.threshold)).join(' 且 ')}
function gradeText(grade:string){return grade.startsWith('PROBABILITY_LIFT_SUPPORTED')?'本次分块检验有概率提升':grade.startsWith('TENTATIVE_PROBABILITY_LIFT')?'概率改善待验证':grade.startsWith('INSUFFICIENT')?'样本不足':'品种／阶段依赖'}
function outcomeStatus(job:MonitorJob){const r=job.metrics.outcome as Record<string,unknown>|undefined;return r?(r.status==='READY'?'概率模型运行 · 匹配 '+(Array.isArray(r.matchedPatterns)?r.matchedPatterns.length:0)+' 个历史组合':'概率模型等待合适周期、行情或活跃品种'):''}
function eventProbabilities(event:MonitorEvent){const stats=event.evidence.historicalStatistics as Record<string,{samples:number;probability:number;matchedBaseProbability:number}>|undefined;if(!stats)return '';return '同品种后段 '+probability(stats.TIME?.probability)+' / 对照 '+probability(stats.TIME?.matchedBaseProbability)+'；留出品种 '+probability(stats.ASSET?.probability)+' / 对照 '+probability(stats.ASSET?.matchedBaseProbability)}
function statistic(value:number|null|undefined){return typeof value==='number'&&Number.isFinite(value)?value.toFixed(3):'—'}
function researchStatus(job:MonitorJob){const r=job.metrics.research as Record<string,unknown>|undefined;if(!r)return '';return r.status==='READY'?({UP:'上升结构',DOWN:'下降结构',MIXED:'方向混合'}[String(r.regime)]??'研究观察')+' · 历史条件未获交易资格':'日线研究数据不足'}
const opportunityLabels:Record<string,string>={HISTORICAL_PROBABILITY_WATCH:'历史条件概率线索',RESEARCH_OBSERVATION_ONLY:'研究观察 · 未证明可交易',LONG_ENTRY_WATCH:'做多入场观察',LONG_EXIT_OR_SHORT_WATCH:'多头退出／做空观察',LONG_PULLBACK_WATCH:'回踩入场观察'}
function keyPrice(event:MonitorEvent,key:string){const value=event.evidence[key];return typeof value==='number'&&Number.isFinite(value)?value.toFixed(4):'—'}
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v)) as T
async function load(){
 if(loading.value)return;loading.value=true;const ticket=++version,kind=props.assetType;error.value=''
 try{const results=await Promise.all([monitoringApi.jobs(kind,query.value,jobPage.value),monitoringApi.events(kind,eventQuery.value,eventPage.value,monitorFilter.value,unread.value)]);if(!alive||ticket!==version)return;jobs.value=results[0].items;jobTotal.value=results[0].total;events.value=results[1].items;eventTotal.value=results[1].total}
 catch(e){if(alive&&ticket===version)error.value=e instanceof Error?e.message:'后台监控读取失败。'}finally{if(alive&&ticket===version)loading.value=false}
}
async function initialize(){try{catalog.value=await monitoringApi.catalog(props.assetType);if(alive)await load()}catch(e){if(alive)error.value=e instanceof Error?e.message:'监控服务暂不可用。'}}
function edit(job?:MonitorJob){if(!catalog.value)return;const parameters=clone({...catalog.value.defaults,...job?.parameters});if(!job&&props.assetType==='OPTION')parameters.bigLots=20;editor.value={id:job?.id,name:job?.name??`${instrumentName(props.symbol)}监控`,symbol:job?.symbol??props.symbol,enabled:job?.enabled??true,seconds:job?.seconds??60,version:job?.version??0,parameters};error.value='';confirmation.value=null}
function opportunityTemplate(kind:'breakout'|'pullback'|'research'|'outcome'){
 edit();if(!editor.value)return
 editor.value.seconds=900
 editor.value.parameters.dailyMaPeriod=kind==='breakout'?20:5
 editor.value.parameters.pullbackTolerancePct=.2
 editor.value.parameters.rules=kind==='breakout'?['DAILY_MA_BREAKOUT_UP','DAILY_MA_BREAKOUT_DOWN']:['DAILY_MA_PULLBACK','DAILY_MA_BREAKOUT_DOWN']
 editor.value.name=kind==='breakout'?'15分钟收盘突破日线MA20':'日线MA5回踩与跌破预警'
 if(kind==='outcome'){editor.value.parameters.dailyMaPeriod=20;editor.value.name='结果反推 · 历史条件概率观察';editor.value.parameters.rules=['OUTCOME_PATTERN'];editor.value.parameters.outcomeTarget='ALL';editor.value.parameters.outcomeEvidence='IMPROVED'}
 if(kind==='research'){editor.value.name='日线趋势与确认拐点（研究观察）';editor.value.parameters.dailyMaPeriod=20;editor.value.parameters.rules=['DAILY_RESEARCH_CONTEXT']}
}
async function save(){if(!editor.value||busy.value)return;busy.value=true;error.value='';try{await monitoringApi.save(props.assetType,editor.value,editor.value.id);editor.value=null;notice.value='监控已保存，由服务器持续运行。首次检查建立基线，不补发历史触发。';await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败。'}finally{busy.value=false}}
async function confirm(){if(!confirmation.value||busy.value)return;busy.value=true;error.value='';try{await confirmation.value.action();confirmation.value=null;notice.value='操作已保存。';await load()}catch(e){error.value=e instanceof Error?e.message:'操作失败。'}finally{busy.value=false}}
function toggle(job:MonitorJob){confirmation.value={title:job.enabled?'暂停后台监控':'恢复后台监控',detail:`${instrumentLabel(job.symbol)} · ${job.name}。${job.enabled?'暂停后不再产生新触发记录。':'恢复时重新建立基线，不补发历史触发。'}`,action:()=>monitoringApi.enabled(props.assetType,job,!job.enabled)}}
function archive(job:MonitorJob){confirmation.value={title:'归档监控任务',detail:`将停止并归档 ${job.name}，已有触发记录保留。`,action:()=>monitoringApi.archive(props.assetType,job)}}
async function ack(event:MonitorEvent){if(busy.value)return;busy.value=true;try{await monitoringApi.acknowledge(props.assetType,event.id);await load()}catch(e){error.value=e instanceof Error?e.message:'标记失败。'}finally{busy.value=false}}
async function searchJobs(){jobPage.value=1;await load()}
async function searchEvents(){eventPage.value=1;await load()}
async function pageEvents(delta:number){eventPage.value+=delta;await load()}
async function pageJobs(delta:number){jobPage.value+=delta;await load()}
watch(()=>props.assetType,()=>{++version;loading.value=false;catalog.value=null;jobs.value=[];events.value=[];editor.value=null;void initialize()})
watch(()=>props.paused,value=>{if(!value)void load()})
onMounted(()=>{void initialize();timer=window.setInterval(()=>{if(!document.hidden&&!props.paused&&!busy.value&&!editor.value&&!confirmation.value)void load()},5000)})
onUnmounted(()=>{alive=false;++version;window.clearInterval(timer)})
</script>
<template>
 <section class="monitor-panel" :aria-label="`${kindLabel}后台监控`">
  <header class="monitor-heading"><div><p class="eyebrow">SERVER MONITOR / {{kindLabel}}</p><h3><Activity :size="17"/>实时入场／出场条件预警</h3><p>当前租户共享 · 关闭页面仍运行 · 按最后保存者的当前权限执行</p></div><div class="actions"><button :disabled="loading||busy" @click="load"><RefreshCw :size="14"/>刷新</button><button v-if="canWrite" class="primary" :disabled="!catalog||!symbol||busy" @click="edit()"><Plus :size="14"/>监控当前{{kindLabel}}合约</button></div></header>
  <div v-if="canWrite" class="monitor-toolbar"><strong>机会预警模板</strong><button :disabled="!catalog||!symbol||busy" @click="opportunityTemplate('breakout')">15分钟突破／跌破日线MA20</button><button :disabled="!catalog||!symbol||busy" @click="opportunityTemplate('pullback')">日线回踩MA5</button><button :disabled="!catalog||!symbol||busy" @click="opportunityTemplate('research')">日线趋势／拐点研究预警</button><button :disabled="!catalog||!symbol||busy" @click="opportunityTemplate('outcome')">结果反推 · 概率预警</button><span>盘中触及与收盘确认分开标记 · 条件预警供判断，不自动下单</span></div>
  <details v-if="catalog?.outcomeResearch" class="event-detail" open><summary>结果反推的条件概率 · {{catalog.outcomeResearch.activeRoots}} 个活跃品种</summary><p>先给历史走势、进出场窗口及转折做结果标签，再用发生之前已知的特征推导组合。{{catalog.outcomeResearch.trainingRoots.length}} 个品种用于推导，另留 {{catalog.outcomeResearch.heldoutRoots.length}} 个品种检验；{{catalog.outcomeResearch.rawBars}} 根原始15分钟柱，生命周期清洗后 {{catalog.outcomeResearch.usableBars}} 根，形成 {{catalog.outcomeResearch.labeledDecisions}} 个带结果标签的决策截面。标签有重叠，不是独立交易笔数。</p><p>活跃标准：主源实际合约此前20个完整日线成交量中位数≥10,000手。名单：{{catalog.outcomeResearch.universeCodes.join('、')}}。</p><p role="status">这里看的是“符合条件后，这类结果相对基准更常出现多少”，不要求100%成功。结果标签概率不等于成本后盈利概率；方向线索、赔率和费用后的期望要分开判断。低频拐点的概率提升也可能有价值。区间为探索性按周分块估计，未作多重检验确证，近期周数不足时不报区间。</p><div class="monitor-table"><table><thead><tr><th>结果目标／证据</th><th>从结果反推的事前条件</th><th>同品种后段：概率／基准／样本</th><th>留出品种：概率／基准／样本</th><th>近期概率／基准</th><th>观察交易均净变动%（后段／留出）</th></tr></thead><tbody><tr v-for="pattern in catalog.outcomeResearch.patterns" :key="pattern.id"><td>{{pattern.label}}<small>{{gradeText(pattern.grade)}}</small></td><td>{{pathText(pattern)}}</td><td>{{probability(pattern.statistics.TIME?.probability)}} / {{probability(pattern.statistics.TIME?.matchedBaseProbability)}}<small>{{pattern.statistics.TIME?.samples??0}} 个截面</small></td><td>{{probability(pattern.statistics.ASSET?.probability)}} / {{probability(pattern.statistics.ASSET?.matchedBaseProbability)}}<small>{{pattern.statistics.ASSET?.samples??0}} 个截面 · {{pattern.statistics.ASSET?.roots??0}} 个品种</small></td><td>{{probability(pattern.statistics.RECENT?.probability)}} / {{probability(pattern.statistics.RECENT?.matchedBaseProbability)}}</td><td>{{statistic(pattern.statistics.TIME?.meanNetPct)}} / {{statistic(pattern.statistics.ASSET?.meanNetPct)}}</td></tr></tbody></table></div><p>入场标签：后续16根内先达到2ATR目标、未先损失1ATR且计成本后为正；转折标签：局部高低点及后续反向变化；离场风险：后续8根有1.5ATR不利波动且末根仍不利。未来数据只用于历史结果标签，实时匹配只用已完成柱。收益列统一是1ATR止损／2ATR目标／最多16柱的独立观察交易；离场风险行是反向观察交易，不能当作实际平仓策略成绩。</p></details>
  <details v-if="catalog?.research" class="event-detail"><summary>历史统计与入场／离场证据 · {{catalog.research.auditedSymbols}} 个品种 · 截至 {{catalog.research.dataEnd}}</summary><p>10 组固定日线特征，比较信号后下一交易日开盘入场、持有 1／3／5／10 个交易日退出，计入假设费用和滑点。开发期选中持有期后不再按后续成绩改选。以下为独立事件均值，不是组合收益或当前胜率，也不能验证 15 分钟／盘中预警。</p><p role="status">本批没有条件通过跨时段稳健性门槛；未获得“最适合入场／离场”的统计证据。可启用研究观察，不能把趋势或已确认拐点当成获利保证。</p><div class="monitor-table"><table><thead><tr><th>日线条件</th><th>开发期选中持有期（非建议）</th><th>2023–2024 样本 / 均净变动%</th><th>2025–2026 样本 / 均净变动%</th><th>后段双倍成本均值%</th></tr></thead><tbody><tr v-for="(item,code) in catalog.research.conditions" :key="code"><td>{{item.label}}</td><td>{{item.developmentSelectedHorizon??'样本不足'}} 个交易日</td><td>{{item.selected?.VALIDATION?.samples??0}} / {{statistic(item.selected?.VALIDATION?.meanNetPct)}}</td><td>{{item.selected?.RETROSPECTIVE_2025_2026?.samples??0}} / {{statistic(item.selected?.RETROSPECTIVE_2025_2026?.meanNetPct)}}</td><td>{{statistic(item.selected?.RETROSPECTIVE_2025_2026?.doubleCostMeanPct)}}</td></tr></tbody></table></div><div v-if="catalog.research.feedbackIteration"><h4>反馈改进后的逐年检验</h4><p>48 个组合候选、12 个对照。每年只用此前三年选条件；未通过训练门槛的年份不选。选中事件 {{catalog.research.feedbackIteration.selectedFoldAggregate.samples}} 条，平均成本后变动 {{statistic(catalog.research.feedbackIteration.selectedFoldAggregate.meanNetPct)}}%，双倍成本 {{statistic(catalog.research.feedbackIteration.selectedFoldAggregate.meanStressPct)}}%；同向／同退出规则对照 {{catalog.research.feedbackIteration.controlFoldAggregate.samples}} 条，均值 {{statistic(catalog.research.feedbackIteration.controlFoldAggregate.meanNetPct)}}%。事件日期和数量不相同，不是随机匹配试验；结果未证明改进有效。</p></div><div v-if="catalog.research.intradayStudy"><h4>15 分钟真实交割合约验证</h4><p>{{catalog.research.intradayStudy.contracts}} 个当前活跃合约，原始 {{catalog.research.intradayStudy.rawBars}} 根，剔除合约代码跨年复用的旧生命周期后 {{catalog.research.intradayStudy.usableBars}} 根。开发期选中持有期，7–9月及10月后比较，不按后段成绩重选。</p><div class="monitor-table"><table><thead><tr><th>条件</th><th>开发期选中持有根数（非建议）</th><th>7–9月样本 / 均净变动%</th><th>10月后样本 / 均净变动%</th><th>后段双倍成本%</th></tr></thead><tbody><tr v-for="(row,key) in catalog.research.intradayStudy.conditions" :key="key"><td>{{row.label}}</td><td>{{row.horizonBars??'不足'}} 根15分钟柱</td><td>{{row.selected?.VALIDATION?.samples??0}} / {{statistic(row.selected?.VALIDATION?.meanNetPct)}}</td><td>{{row.selected?.RECENT_COMPARISON?.samples??0}} / {{statistic(row.selected?.RECENT_COMPARISON?.meanNetPct)}}</td><td>{{statistic(row.selected?.RECENT_COMPARISON?.doubleCostMeanPct)}}</td></tr></tbody></table></div><p>当前活跃合约选择存在幸存者偏差；不是历史全市场可投资样本。15分钟触及收回只是代理条件，不能给逐笔盘中回踩赋予已验证胜率。新预警依据会附对应范围的统计资格。</p></div><p>MA20 斜率、MA5/20 排列、完整柱量比及高低枢轴参与趋势／拐点观察；枢轴要等右侧两根日线确认。样本仅覆盖主力活跃期中相同交割合约窗口；历史日期曾被项目研究使用，非全新前瞻证据。只输出观察及风险提示，不自动开平仓。</p></details>
  <p v-if="paused" class="monitor-note">页面刷新已暂停；服务器监控仍继续。停止任务请使用下方“暂停”。</p>
  <p v-if="notice" class="monitor-notice" role="status">{{notice}}</p><p v-if="error" class="monitor-error" role="alert">{{error}} <button @click="initialize">重试</button></p>
  <div v-if="confirmation" class="monitor-confirm" role="alertdialog" :aria-label="confirmation.title"><strong>{{confirmation.title}}</strong><p>{{confirmation.detail}}</p><button :disabled="busy" @click="confirmation=null">取消</button><button :disabled="busy" @click="confirm">确认操作</button></div>
  <form v-if="editor" class="monitor-editor" aria-label="监控规则配置" @submit.prevent="save"><fieldset :disabled="busy"><div class="editor-grid"><label>任务名称<input v-model="editor.name" required maxlength="80" aria-label="监控任务名称"/></label><label>绑定合约<input :value="instrumentLabel(editor.symbol)" readonly aria-label="监控绑定合约"/></label><label>技术指标周期<select v-model.number="editor.seconds" aria-label="监控 K 线周期"><option v-for="s in (editor.parameters.rules.includes('OUTCOME_PATTERN')?[900]:(catalog?.frequencies??[]))" :key="s" :value="s">{{s/60}} 分钟</option></select></label><label v-if="editor.parameters.rules.includes('OUTCOME_PATTERN')">概率预警目标<select v-model="editor.parameters.outcomeTarget"><option value="ALL">全部方向</option><option value="ENTRY">入场窗口</option><option value="EXIT">离场风险</option><option value="TURN">转折候选</option><option value="TREND">走势方向</option></select></label><label v-if="editor.parameters.rules.includes('OUTCOME_PATTERN')">证据范围<select v-model="editor.parameters.outcomeEvidence"><option value="IMPROVED">概率改善及待验证候选</option><option value="ALL">含品种／阶段依赖的探索条件</option></select></label><template v-if="!editor.parameters.rules.includes('OUTCOME_PATTERN')"><label>日线均线周期<input v-model.number="editor.parameters.dailyMaPeriod" type="number" min="2" max="180" required aria-label="日线均线周期"/></label><label>回踩接近范围 / %<input v-model.number="editor.parameters.pullbackTolerancePct" type="number" min="0" max="5" step="0.05" required aria-label="回踩容差"/></label><label>60 秒涨跌阈值 / %<input v-model.number="editor.parameters.jumpPct" type="number" min="0.1" max="1000" step="0.1" required aria-label="60 秒涨跌阈值"/></label><label>大额成交增量 / 手<input v-model.number="editor.parameters.bigLots" type="number" min="1" max="1000000" step="1" required aria-label="大额成交手数"/></label><label>放量倍数<input v-model.number="editor.parameters.volumeMultiple" type="number" min="1" max="100" step="0.1" required aria-label="放量倍数"/></label><label>通道／量能回看根数<input v-model.number="editor.parameters.lookback" type="number" min="5" max="120" step="1" required/></label><label>布林标准差倍数<input v-model.number="editor.parameters.bollStd" type="number" min="0.5" max="10" step="0.1" required/></label><label>ATR 倍数<input v-model.number="editor.parameters.atrMultiple" type="number" min="0.5" max="20" step="0.1" required/></label><label>技术／涨跌提示冷却 / 秒<input v-model.number="editor.parameters.cooldownSeconds" type="number" min="10" max="3600" step="1" required/></label><label>背离枢轴右侧确认根数<input v-model.number="editor.parameters.pivotBars" type="number" min="1" max="5" step="1" required/></label></template><label class="inline"><input v-model="editor.enabled" type="checkbox"/>保存后启用</label></div><div v-if="!editor.parameters.rules.includes('OUTCOME_PATTERN')" class="ma-picks"><span>均线突破：</span><label v-for="ma in [5,10,20,60,180]" :key="ma" class="inline"><input v-model="editor.parameters.maPeriods" type="checkbox" :value="ma"/>MA{{ma}}</label></div><details open class="rule-picks"><summary>监控条件（{{editor.parameters.rules.length}} 项）</summary><div><label v-for="rule in catalog?.rules??[]" :key="rule.code" class="inline"><input v-model="editor.parameters.rules" type="checkbox" :value="rule.code"/>{{rule.label}}</label></div></details><p v-if="editor.parameters.rules.includes('OUTCOME_PATTERN')" class="monitor-note">结果反推模型固定使用15分钟和已完成日线特征；这里选择目标和证据范围，不能把旧规则的阈值修改冒充模型重新训练。原始标签定义、推导组合和成本假设见上方实验说明。</p><p class="monitor-note">跨周期预警中，日线均线只使用已完成日线；突破／跌破按所选分钟周期收盘确认，回踩为盘中从上方接近均线范围的未确认提示，不等于支撑有效。主连保存时绑定到主源确认的实际交割合约，不自动换月。放量突破按上一组完整 K 线判断；MACD 为 12/26/9，背离在后续 K 线确认后记录。大额成交按 Tick 增量手数及估算方向判断，不代表逐笔委托或主力身份。</p><div class="actions"><button type="button" @click="editor=null">取消</button><button class="primary" :disabled="!editor.parameters.rules.length">{{busy?'正在保存…':'保存后台监控'}}</button></div></fieldset></form>
  <form class="monitor-toolbar" @submit.prevent="searchJobs"><input v-model="query" placeholder="搜索任务名称或合约" aria-label="搜索监控任务"/><button :disabled="loading||busy">查询任务</button><span>{{jobTotal}} 个任务 · 每租户最多 {{catalog?.maxEnabledPerTenant??20}} 个启用</span></form>
  <div class="monitor-table"><table><thead><tr><th>任务 / 绑定合约</th><th>运行状态</th><th>最近检查 / 行情时点</th><th>操作</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td><strong>{{job.name}}</strong><small>{{instrumentLabel(job.symbol)}} · {{job.seconds/60}} 分钟 · {{job.parameters.rules.length}} 条规则</small></td><td><span :class="['status',job.status.toLowerCase()]">{{states[job.status]??job.status}}</span><small>{{job.message}}</small><small v-if="outcomeStatus(job)">{{outcomeStatus(job)}}</small><small v-if="researchStatus(job)">{{researchStatus(job)}}</small><small v-if="job.enabled&&job.checkedAt&&Date.now()-Date.parse(job.checkedAt)>30000">检查心跳已超过 30 秒，请检查后台服务。</small></td><td><time>{{formatTime(job.checkedAt)}}</time><small>行情 {{formatTime(job.sourceTimestamp)}}</small></td><td class="row-actions"><button v-if="canWrite" :disabled="busy" @click="edit(job)">编辑规则</button><button v-if="canWrite" :disabled="busy" @click="toggle(job)">{{job.enabled?'暂停':'恢复'}}</button><button v-if="canWrite" :disabled="busy" @click="archive(job)">归档</button></td></tr></tbody></table><p v-if="!jobs.length" class="empty">{{loading?'正在读取后台任务…':'还没有后台监控；可为当前合约创建任务。'}}</p></div>
  <div v-if="jobTotal>20" class="monitor-pagination"><span>任务第 {{jobPage}} 页</span><button :disabled="jobPage<=1||loading" @click="pageJobs(-1)">上一页</button><button :disabled="jobPage*20>=jobTotal||loading" @click="pageJobs(1)">下一页</button></div>
  <header class="events-heading"><h4><BellRing :size="16"/>入场／出场条件触发记录</h4><span>{{eventTotal}} 条 · 首次建立基线不补历史提醒</span></header><form class="monitor-toolbar" @submit.prevent="searchEvents"><input v-model="eventQuery" placeholder="合约 / 信号 / 规则编码" aria-label="搜索监控触发"/><select v-model="monitorFilter" aria-label="触发任务筛选"><option value="">全部任务</option><option v-for="job in jobs" :key="job.id" :value="job.id">{{job.name}}</option></select><label class="inline"><input v-model="unread" type="checkbox"/>仅未读</label><button :disabled="loading||busy">查询记录</button></form>
  <div class="monitor-table"><table><thead><tr><th>确认行情时点</th><th>合约</th><th>触发条件</th><th>机会方向 / 确认 / 价位</th><th>记录时间</th><th>操作</th></tr></thead><tbody><tr v-for="event in events" :key="event.id"><td>{{formatTime(event.observedAt)}}</td><td class="mono">{{instrumentLabel(event.symbol)}}</td><td><strong>{{event.label}}</strong><small>{{event.rule}}</small></td><td>{{opportunityLabels[String(event.evidence.opportunity)]??'规则触发'}}<small>{{event.evidence.confirmation==='BAR_CLOSE'?'收盘已确认':event.evidence.confirmation==='INTRABAR_TOUCH'?'盘中触及 · 未确认':event.evidence.confirmation==='DAILY_CLOSE_CONFIRMED'?'日线已确认 · 有确认延迟':'查看依据'}}</small><small v-if="event.evidence.historicalStatistics">{{eventProbabilities(event)}}<br/>是对应结果标签的历史频率，非当前保证；依据中可查看条件和样本。</small><small v-if="event.evidence.statisticalAssessment">统计资格：未获得稳健交易优势</small><small v-if="event.evidence.studyDirection">研究方向：{{event.evidence.studyDirection===1?'向上／空头退出观察':'向下／多头退出观察'}}</small><small v-if="event.evidence.dailyMA!=null">触发价 {{keyPrice(event,'close')!=='—'?keyPrice(event,'close'):keyPrice(event,'price')}} / 日线MA{{event.evidence.maPeriod}} {{keyPrice(event,'dailyMA')}}</small></td><td>{{formatTime(event.createdAt)}}</td><td class="row-actions"><button v-if="assetType==='FUTURE'" @click="emit('inspect',event.symbol)">查看该合约</button><button @click="detail=event">触发依据</button><button v-if="canWrite&&!event.acknowledgedAt" :disabled="busy" @click="ack(event)">标记已读</button><span v-else-if="event.acknowledgedAt">已读</span></td></tr></tbody></table><p v-if="!events.length" class="empty">没有触发记录。休市、过时、历史不足和窗口预热均不会补造信号。</p></div>
  <div class="monitor-pagination"><span>触发记录第 {{eventPage}} 页</span><button :disabled="eventPage<=1||loading" @click="pageEvents(-1)">上一页</button><button :disabled="eventPage*20>=eventTotal||loading" @click="pageEvents(1)">下一页</button></div>
  <section v-if="detail" class="event-detail" aria-label="监控触发依据"><header><h4>{{instrumentLabel(detail.symbol)}} · {{detail.label}}</h4><button @click="detail=null">关闭详情</button></header><p>确认行情时点 {{formatTime(detail.observedAt)}} · 保存 {{formatTime(detail.createdAt)}} · {{detail.algorithmVersion}}</p><pre>{{JSON.stringify(detail.evidence,null,2)}}</pre></section>
 </section>
</template>
